  const timeOffsetInMS = date.getTimezoneOffset() * 60000
  date.setTime(date.getTime() - timeOffsetInMS)
  const datestr = date.toISOString().substr(0, 10)
  const tup = datestr.split('-')
  return new Date(Number(tup[0]), Number(tup[1])-1, Number(tup[2]))
}

function oldUnlocalDate(date) {
  const datestr = date.toISOString().substr(0, 10)
  const tup = datestr.split('-')
  return new Date(Number(tup[0]), Number(tup[1])-1, Number(tup[2]))
}

// Scenario A: value initially set from Python as UTC midnight epoch for 2019-09-20 (typical bokeh datetime.date sync)
const epochMidnightUTC = Date.parse("2019-09-20T00:00:00.000Z")

console.log("TZ =", process.env.TZ)
console.log("getTimezoneOffset (minutes) =", new Date(epochMidnightUTC).getTimezoneOffset())

const newResult = _unlocal_date(new Date(epochMidnightUTC))
const oldResult = oldUnlocalDate(new Date(epochMidnightUTC))
console.log("NEW _unlocal_date result (local):", newResult.toString(), " -> pikaday would show day:", newResult.getDate())
console.log("OLD _unlocal_date result (local):", oldResult.toString(), " -> pikaday would show day:", oldResult.getDate())

// Scenario B: value set via toDateString() round trip after on-select in browser-local time (the original bug repro), e.g. user selected Sept 20 while in UTC+2 France
const localMidnightStr = "Fri Sep 20 2019" // toDateString() output for a Date at local midnight Sept 20
const dNew = new Date(localMidnightStr)
console.log("\nScenario B: parsed from toDateString string:", dNew.toISOString())
const newResultB = _unlocal_date(new Date(dNew))
const oldResultB = oldUnlocalDate(new Date(dNew))
console.log("NEW result day:", newResultB.getDate(), newResultB.toString())
console.log("OLD result day:", oldResultB.getDate(), oldResultB.toString())
EOF
